      "text": "Diagnosis of squamous cell carcinoma of unknown (or occult) primary.",
      "quote": "Diagnosis of squamous cell carcinoma of unknown (or occult) primary",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Patients who are committed to an institution by virtue of an order issued either by the judicial or the administrative authorities.",
      "quote": "Patients who are committed to an institution by virtue of an order issued either by the judicial or the administrative authorities",
      "thresholds": []
    },
